#include "../../04-图论/动态点分治.cpp"
int main(){mt19937 r(113);for(int t=0;t<80;t++){int n=1+r()%100;vector<vector<pair<int,long long>>>g(n);for(int i=1;i<n;i++){int p=r()%i,w=r()%11;g[i].push_back({p,w});g[p].push_back({i,w});}DynamicCentroid c(g);vector<bool> on(n);for(int k=0;k<500;k++){int u=r()%n;if(r()%2){on[u]=!on[u];c.set_active(u,on[u]);}else{vector<long long>d(n,-1);d[u]=0;vector<int>q={u};for(int i=0;i<(int)q.size();i++)for(auto [v,w]:g[q[i]])if(d[v]<0)d[v]=d[q[i]]+w,q.push_back(v);long long want=DynamicCentroid::INF;for(int i=0;i<n;i++)if(on[i])want=min(want,d[i]);assert(c.query(u)==want);}}}}
